const webhookItem = $('Webhook1').first()?.json ?? {};
const job = webhookItem.body ?? webhookItem;
const event = String(job?.event || '').toLowerCase();

if (event !== 'job_created') {
  return [];
}

if (!job || !job.job_id) {
  throw new Error('Missing job_id from webhook payload. Keys: ' + Object.keys(job || {}).join(', '));
}

const jobId = Number(job.job_id);
const jobTitleRaw = String(job.title || 'this job');
const jobTitle = String(job.title || 'this job').toLowerCase();
const requiredEducationRaw = String(job.educational_attainment_required || '').trim();

const WEIGHTS = {
  exact: 1.0,
  alias: 0.85,
  parent_group: 0.8,
  grammar: 0.7,
};

const normalizeText = (value) => String(value || '')
  .normalize('NFKD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .replace(/[^a-z0-9+#./&\s-]/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

const escapeRegExp = (value) => String(value || '').replace(/[.*+?^{}()|[\]\\]/g, '\\$&');

const containsPhrase = (haystack, phrase) => {
  const normalizedHaystack = normalizeText(haystack);
  const normalizedPhrase = normalizeText(phrase);
  if (!normalizedHaystack || !normalizedPhrase) {
    return false;
  }

  const pattern = new RegExp('(^|\\s)' + escapeRegExp(normalizedPhrase).replace(/\\ /g, '\\s+') + '(?=\\s|$)');
  return pattern.test(normalizedHaystack);
};

const tokenize = (text) => normalizeText(text).split(/\s+/).filter(Boolean);

const stemTokenAggressive = (token) => {
  let stem = normalizeText(token);
  if (stem.length <= 2) {
    return stem;
  }

  const suffixRules = [
    ['izations', 'ize'],
    ['ization', 'ize'],
    ['ational', 'ate'],
    ['ations', 'ate'],
    ['ation', 'ate'],
    ['ments', 'ment'],
    ['ment', ''],
    ['ingly', ''],
    ['edly', ''],
    ['ings', ''],
    ['ing', ''],
    ['ed', ''],
    ['izers', 'ize'],
    ['izer', 'ize'],
    ['ers', 'er'],
    ['er', ''],
    ['ies', 'y'],
    ['ied', 'y'],
    ['s', ''],
  ];

  for (const [suffix, replacement] of suffixRules) {
    if (stem.endsWith(suffix) && stem.length - suffix.length >= 3) {
      stem = stem.slice(0, -suffix.length) + replacement;
      break;
    }
  }

  return stem;
};

const parseSkillArray = (raw) => {
  let value = raw;
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      value = [value];
    }
  }

  if (!Array.isArray(value) && typeof value === 'object' && value !== null) {
    value = Object.values(value);
  }

  if (!Array.isArray(value)) {
    value = [];
  }

  return value.map((item) => String(item || '').trim()).filter(Boolean);
};

const parseParentheticalSkill = (skill) => {
  const raw = String(skill || '');
  const groups = [...raw.matchAll(/\(([^)]+)\)/g)]
    .map((match) => String(match[1] || '').trim())
    .filter(Boolean);

  const base = raw.replace(/\([^)]*\)/g, ' ').replace(/\s+/g, ' ').trim();
  const children = [];

  for (const group of groups) {
    const parts = group
      .split(/,|;|\band\b|&/i)
      .map((piece) => piece.trim())
      .filter(Boolean);

    for (const piece of parts) {
      children.push(piece);
    }
  }

  return {
    raw,
    base,
    children,
  };
};

const expandSlashVariants = (value) => {
  const text = String(value || '').trim();
  if (!text) {
    return [];
  }

  const variants = new Set([text]);
  if (text.includes('/')) {
    text
      .split('/')
      .map((part) => part.trim())
      .filter(Boolean)
      .forEach((part) => variants.add(part));
  }

  return Array.from(variants);
};

const uniqueNormalized = (values) => {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const normalized = normalizeText(value);
    if (!normalized || seen.has(normalized)) {
      continue;
    }

    seen.add(normalized);
    output.push(normalized);
  }

  return output;
};

const buildAliasIndex = (dynamicAliases) => {
  const builtIn = {
    javascript: ['js', 'java script'],
    'node.js': ['nodejs', 'node js', 'node'],
    typescript: ['ts'],
    'c#': ['c sharp', 'csharp'],
    'c++': ['cpp', 'c plus plus'],
    mysql: ['my sql'],
    postgresql: ['postgres', 'postgre sql'],
    mongodb: ['mongo', 'mongo db'],
    'project management': ['pm', 'project manager', 'project managers'],
    'quality assurance': ['qa'],
    'user interface design': ['ui design', 'ui ux', 'ux ui'],
    networking: ['tcp ip', 'dns', 'vpn'],
    'web development': ['html css', 'frontend development', 'front end development'],
    'database management': ['db management', 'database administration', 'dba'],
  };

  const map = new Map();

  const addAlias = (canonical, alias) => {
    const canonicalKey = normalizeText(canonical);
    const aliasKey = normalizeText(alias);
    if (!canonicalKey || !aliasKey) {
      return;
    }

    if (!map.has(canonicalKey)) {
      map.set(canonicalKey, new Set());
    }

    map.get(canonicalKey).add(aliasKey);
  };

  for (const [canonical, aliases] of Object.entries(builtIn)) {
    aliases.forEach((alias) => addAlias(canonical, alias));
  }

  const queue = Array.isArray(dynamicAliases) ? [...dynamicAliases] : [dynamicAliases];
  while (queue.length > 0) {
    const entry = queue.shift();
    if (!entry) {
      continue;
    }

    if (Array.isArray(entry)) {
      queue.push(...entry);
      continue;
    }

    if (typeof entry === 'string') {
      const parts = entry.split('=>').map((part) => part.trim()).filter(Boolean);
      if (parts.length === 2) {
        addAlias(parts[0], parts[1]);
      }
      continue;
    }

    if (typeof entry !== 'object') {
      continue;
    }

    if (entry.canonical && entry.alias) {
      addAlias(entry.canonical, entry.alias);
    }

    if (entry.canonical && Array.isArray(entry.aliases)) {
      entry.aliases.forEach((alias) => addAlias(entry.canonical, alias));
    }

    if (entry.skill && Array.isArray(entry.aliases)) {
      entry.aliases.forEach((alias) => addAlias(entry.skill, alias));
    }

    if (!entry.canonical && !entry.skill) {
      for (const [canonical, aliases] of Object.entries(entry)) {
        if (Array.isArray(aliases)) {
          aliases.forEach((alias) => addAlias(canonical, alias));
        } else {
          addAlias(canonical, aliases);
        }
      }
    }
  }

  return map;
};

const buildSkillSpec = (requiredSkill, aliasIndex) => {
  const parsed = parseParentheticalSkill(requiredSkill);
  const canonical = normalizeText(parsed.base || parsed.raw);
  const children = uniqueNormalized(parsed.children.flatMap(expandSlashVariants));

  const aliasCandidates = new Set();
  aliasCandidates.add(canonical);
  aliasCandidates.add(canonical.replace(/\./g, ''));
  aliasCandidates.add(canonical.replace(/\s+/g, ''));

  if (aliasIndex.has(canonical)) {
    for (const alias of aliasIndex.get(canonical)) {
      aliasCandidates.add(alias);
    }
  }

  const aliases = uniqueNormalized(Array.from(aliasCandidates));
  const grammarTerms = uniqueNormalized([canonical, ...aliases, ...children]);

  return {
    raw: String(requiredSkill || '').trim(),
    canonical,
    aliases,
    children,
    grammarTerms,
  };
};

const buildEvidenceContext = (resumeText, parsedSkills) => {
  const resumeNormalized = normalizeText(resumeText);
  const parsedNormalized = uniqueNormalized(parsedSkills);
  const parsedSet = new Set(parsedNormalized);

  const combinedTokens = [
    ...tokenize(resumeNormalized),
    ...parsedNormalized.flatMap((skill) => tokenize(skill)),
  ];

  const stemSet = new Set(combinedTokens.map((token) => stemTokenAggressive(token)).filter(Boolean));

  return {
    resumeNormalized,
    parsedSet,
    stemSet,
  };
};

const evaluateSkillMatch = (spec, context) => {
  const exactMatch = [spec.canonical].find((term) => term && (containsPhrase(context.resumeNormalized, term) || context.parsedSet.has(term)));
  if (exactMatch) {
    return { matched: true, weight: WEIGHTS.exact, type: 'exact', term: exactMatch };
  }

  const aliasMatch = spec.aliases.find((term) => term && (containsPhrase(context.resumeNormalized, term) || context.parsedSet.has(term)));
  if (aliasMatch) {
    return { matched: true, weight: WEIGHTS.alias, type: 'alias', term: aliasMatch };
  }

  const parentGroupMatch = spec.children.find((term) => term && (containsPhrase(context.resumeNormalized, term) || context.parsedSet.has(term)));
  if (parentGroupMatch) {
    return { matched: true, weight: WEIGHTS.parent_group, type: 'parent_group', term: parentGroupMatch };
  }

  const grammarMatch = spec.grammarTerms.find((term) => {
    const tokens = tokenize(term);
    if (tokens.length === 0) {
      return false;
    }
    return tokens.every((token) => context.stemSet.has(stemTokenAggressive(token)));
  });

  if (grammarMatch) {
    return { matched: true, weight: WEIGHTS.grammar, type: 'grammar', term: grammarMatch };
  }

  return { matched: false, weight: 0, type: null, term: null };
};

const normalizeNoSymbols = (value) => normalizeText(value).replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

const educationLevels = [
  { level: 'doctorate', rank: 5, keywords: ['doctorate', 'doctoral', 'phd', 'doctor of philosophy'] },
  { level: 'masters', rank: 4, keywords: ['master', 'masters', "master's", 'm.s', 'ms', 'm.a', 'ma', 'mba'] },
  { level: 'bachelors', rank: 3, keywords: ['bachelor', 'bachelors', "bachelor's", 'b.s', 'bs', 'b.a', 'ba', 'college graduate', 'college grad', 'degree'] },
  { level: 'associate', rank: 2, keywords: ['associate degree', 'associate'] },
  { level: 'vocational', rank: 2, keywords: ['vocational', 'tesda', 'certificate', 'technical-vocational', 'nc ii', 'nc iii'] },
  { level: 'highschool', rank: 1, keywords: ['high school', 'secondary', 'senior high', 'shs'] },
];

const inferEducationLevel = (value) => {
  const normalized = normalizeNoSymbols(value);
  if (!normalized || ['any', 'not specified', 'none', 'n a', 'na'].includes(normalized)) {
    return null;
  }

  for (const item of educationLevels) {
    if (item.keywords.some((keyword) => normalized.includes(normalizeNoSymbols(keyword)))) {
      return item.level;
    }
  }

  return null;
};

const levelRank = (level) => {
  const found = educationLevels.find((item) => item.level === level);
  return found ? found.rank : null;
};

const isEducationRequired = (() => {
  const normalized = normalizeText(requiredEducationRaw);
  return normalized !== '' && !['any', 'not specified', 'none', 'n/a', 'na'].includes(normalized);
})();

const requiredEducationLevel = inferEducationLevel(requiredEducationRaw);
const requiredSkillsRaw = parseSkillArray(job.skills_required ?? job.required_skills ?? []);
const aliasIndex = buildAliasIndex([job.skill_aliases ?? null, webhookItem.skill_aliases ?? null]);
const requiredSpecs = requiredSkillsRaw.map((skill) => buildSkillSpec(skill, aliasIndex));
const requiredSkillsText = requiredSkillsRaw.length > 0 ? requiredSkillsRaw.join(', ') : 'Not specified';

const candidates = $input.all().map((item) => item.json);
const matchedCandidates = [];

for (const candidate of candidates) {
  const resumeRaw = String(candidate.resume_text || '');
  const candidateEducationRaw = String(candidate.educational_attainment || '').trim();
  const candidateParsedSkills = parseSkillArray(candidate.parsed_skill ?? []);

  let candidateEducationLevel = inferEducationLevel(candidateEducationRaw);
  if (!candidateEducationLevel) {
    candidateEducationLevel = inferEducationLevel(resumeRaw);
  }

  if (isEducationRequired) {
    let educationQualified = false;

    if (requiredEducationLevel && candidateEducationLevel) {
      educationQualified = Number(levelRank(candidateEducationLevel) || 0) >= Number(levelRank(requiredEducationLevel) || 0);
    } else {
      const requiredNormalized = normalizeNoSymbols(requiredEducationRaw);
      const candidateNormalized = normalizeNoSymbols(candidateEducationRaw);
      educationQualified = candidateNormalized !== '' && (
        candidateNormalized === requiredNormalized ||
        candidateNormalized.includes(requiredNormalized)
      );
    }

    if (!educationQualified) {
      const seekerEducationLabel = candidateEducationRaw || 'Not specified';
      const reason = 'Auto-disqualified: requires ' + requiredEducationRaw + ', applicant has ' + seekerEducationLabel + '.';
      const seekerName = String(candidate.name || 'Jobseeker');

      matchedCandidates.push({
        job_id: jobId,
        user_id: candidate.id,
        name: seekerName,
        email: candidate.email,
        matchScore: 0,
        inferred_edu: candidateEducationLevel || 'unknown',
        disqualified: true,
        reason,
        email_subject: 'Not Qualified for ' + jobTitleRaw,
        email_body: 'Hi ' + seekerName + ',<br/><br/>You are not qualified for <b>' + jobTitleRaw + '</b> because the job requires <b>' + requiredEducationRaw + '</b> and your profile currently shows <b>' + seekerEducationLabel + '</b>.<br/><br/>Please apply to jobs that match your educational attainment.<br/><br/>Best regards,<br/>CityJobLink Team',
      });

      continue;
    }
  }

  const context = buildEvidenceContext(resumeRaw, candidateParsedSkills);
  if (context.resumeNormalized.length < 5 && candidateParsedSkills.length === 0) {
    continue;
  }

  let score = 0;
  const details = [];

  if (candidateEducationLevel) {
    details.push('Education level: ' + candidateEducationLevel);
  }

  const titleKeywords = tokenize(jobTitle).filter((word) => word.length > 3);
  const titleHits = titleKeywords.filter((word) => containsPhrase(context.resumeNormalized, word)).length;

  if (titleKeywords.length > 0 && titleHits > 0) {
    const titleScore = (titleHits / titleKeywords.length) * 30;
    score += titleScore;
    details.push('Title alignment: ' + titleHits + '/' + titleKeywords.length + ' keyword hit/s');
  }

  let matchedRequiredCount = 0;
  let weightedSkillHits = 0;
  const matchTypeCounts = { exact: 0, alias: 0, parent_group: 0, grammar: 0 };

  for (const spec of requiredSpecs) {
    const result = evaluateSkillMatch(spec, context);
    if (!result.matched) {
      continue;
    }

    matchedRequiredCount += 1;
    weightedSkillHits += result.weight;
    if (result.type && matchTypeCounts[result.type] !== undefined) {
      matchTypeCounts[result.type] += 1;
    }
  }

  const skillScore = requiredSpecs.length > 0 ? (weightedSkillHits / requiredSpecs.length) * 70 : 0;
  score += skillScore;

  if (requiredSpecs.length > 0) {
    details.push(
      'Skills matched: ' + matchedRequiredCount + '/' + requiredSpecs.length +
      ' | weighted=' + weightedSkillHits.toFixed(2) +
      ' | exact=' + matchTypeCounts.exact +
      ', alias=' + matchTypeCounts.alias +
      ', parent_group=' + matchTypeCounts.parent_group +
      ', grammar=' + matchTypeCounts.grammar
    );
  }

  const matchScore = Math.round(Math.min(score, 100));
  const seekerName = String(candidate.name || 'Jobseeker');

  matchedCandidates.push({
    job_id: jobId,
    user_id: candidate.id,
    name: seekerName,
    email: candidate.email,
    matchScore,
    inferred_edu: candidateEducationLevel || 'unknown',
    disqualified: false,
    reason: details.length > 0 ? details.join(' | ') : 'No direct matches found',
    email_subject: matchScore + '% Match! New Job Alert: ' + jobTitleRaw,
    email_body: 'Hi ' + seekerName + ',<br/><br/>Great news! Our matching engine found a new job that fits your profile.<br/><br/><b>Match Score:</b> ' + matchScore + '%<br/><b>Required Skills:</b> ' + requiredSkillsText + '<br/><b>Match Reason:</b> ' + (details.length > 0 ? details.join(' | ') : 'General profile fit') + '<br/><br/>Log in to CityJobLink to apply now!<br/><br/>Best regards,<br/>CityJobLink Team',
  });
}

matchedCandidates.sort((a, b) => Number(b.matchScore) - Number(a.matchScore));

return matchedCandidates.map((match) => ({ json: match }));
